Built it with the iOS/Android platform rules in mind: 48×48dp Android / 44×44pt iOS touch targets, destructive-action-sheet-on-iOS vs two-button-dialog-on-Android for the irreversible delete, a dark-mode elevation ladder (lighter surfaces per layer, not shadows), Dynamic Type–safe text (no truncation, `minHeight` not `height`), and safe-area insets.

Two files — a token/theme module and the screen:

```tsx
// theme.ts
import { useColorScheme } from 'react-native';

const primitives = {
  gray: {
    50: '#FAFAFA', 100: '#F2F2F3', 200: '#E4E4E6', 300: '#D1D1D4',
    600: '#6B6B70', 800: '#2C2C2E', 900: '#1C1C1E', 950: '#121214',
  },
  blue: { 600: '#0A84FF' },
  red: { 600: '#D70015', 700: '#FF453A' },
};

// Elevation ladder: nearer surfaces get lighter (not shadowed) in dark mode.
// Light theme carries the same ladder via shadow instead.
const light = {
  bgApp: primitives.gray[50],
  bgSurface: '#FFFFFF',
  bgSurfaceRaised: '#FFFFFF',
  borderSubtle: primitives.gray[200],
  textPrimary: primitives.gray[950],
  textMuted: primitives.gray[600],
  accentSolid: primitives.blue[600],
  dangerText: primitives.red[600],
  overlayScrim: 'rgba(0,0,0,0.4)',
};

const dark = {
  bgApp: primitives.gray[950],
  bgSurface: primitives.gray[900],
  bgSurfaceRaised: primitives.gray[800],
  borderSubtle: '#38383A',
  textPrimary: '#FFFFFF',
  textMuted: '#9A9AA0',
  accentSolid: '#409CFF',
  dangerText: primitives.red[700],
  overlayScrim: 'rgba(0,0,0,0.6)',
};

export type Theme = typeof light;

export function useTheme(): Theme {
  const scheme = useColorScheme();
  return scheme === 'dark' ? dark : light;
}
