```tsx
// AccountSettingsScreen.tsx
import React, { useState, useCallback } from 'react';
import {
  View,
  Text,
  Image,
  Pressable,
  ScrollView,
  Switch,
  Alert,
  ActionSheetIOS,
  Platform,
  ActivityIndicator,
  StyleSheet,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useTheme, Theme } from './theme';

export interface AccountSettingsUser {
  name: string;
  email: string;
  avatarUrl?: string;
}

export interface AccountSettingsScreenProps {
  user: AccountSettingsUser;
  onEditProfile: () => void;
  onNavigate: (route: 'notifications' | 'privacy' | 'security' | 'language' | 'help' | 'about') => void;
  notificationsEnabled: boolean;
  onToggleNotifications: (next: boolean) => void;
  onLogout: () => void;
  onDeleteAccount: () => Promise<void>;
}

type RowItem = {
  key: string;
  label: string;
  onPress: () => void;
  destructive?: boolean;
  disabled?: boolean;
  accessory?: React.ReactNode;
  accessibilityHint?: string;
};

function Row({ item, theme }: { item: RowItem; theme: Theme }) {
  return (
    <Pressable
      onPress={item.onPress}
      disabled={item.disabled}
      accessibilityRole="button"
      accessibilityLabel={item.label}
      accessibilityHint={item.accessibilityHint}
      accessibilityState={{ disabled: item.disabled }}
      style={({ pressed }) => [
        styles.row,
        { backgroundColor: pressed ? theme.bgSurfaceRaised : theme.bgSurface },
        item.disabled && { opacity: 0.5 },
      ]}
    >
      <Text
        style={[
          styles.rowLabel,
          { color: item.destructive ? theme.dangerText : theme.textPrimary },
        ]}
      >
        {item.label}
      </Text>
      {item.accessory}
    </Pressable>
  );
}

function Chevron({ color }: { color: string }) {
  return (
    <Text style={{ color, fontSize: 18 }} accessibilityElementsHidden importantForAccessibility="no">
      {'\u203A'}
    </Text>
  );
}

function SectionCard({ children, theme }: { children: React.ReactNode; theme: Theme }) {
  return (
    <View style={[styles.card, { backgroundColor: theme.bgSurface, borderColor: theme.borderSubtle }]}>
      {children}
    </View>
  );
}

function Divider({ theme }: { theme: Theme }) {
  return <View style={[styles.divider, { backgroundColor: theme.borderSubtle }]} />;
}

export default function AccountSettingsScreen({
  user,
  onEditProfile,
  onNavigate,
  notificationsEnabled,
  onToggleNotifications,
  onLogout,
  onDeleteAccount,
}: AccountSettingsScreenProps) {
  const theme = useTheme();
  const insets = useSafeAreaInsets();
  const [deleting, setDeleting] = useState(false);

  const confirmDelete = useCallback(() => {
    const title = 'Delete account?';
    const message =
      'This permanently removes your profile, settings and data. This cannot be undone.';

    const runDelete = async () => {
      setDeleting(true);
      try {
        await onDeleteAccount();
      } catch (err) {
        Alert.alert('Couldn\u2019t delete account', 'Please try again.');
      } finally {
        setDeleting(false);
      }
    };

    if (Platform.OS === 'ios') {
      // HIG: destructive choice in an action sheet, Cancel separate at the bottom.
      ActionSheetIOS.showActionSheetWithOptions(
        {
          title,
          message,
          options: ['Delete Account', 'Cancel'],
          destructiveButtonIndex: 0,
          cancelButtonIndex: 1,
        },
        (index) => {
          if (index === 0) runDelete();
        },
      );
    } else {
      // Material: dialog with at most two actions, one confirms, one dismisses.
      Alert.alert(title, message, [
        { text: 'Cancel', style: 'cancel' },
        { text: 'Delete', style: 'destructive', onPress: runDelete },
      ]);
    }
  }, [onDeleteAccount]);

  const settingsRows: RowItem[] = [
    { key: 'notifications', label: 'Notifications', onPress: () => onNavigate('notifications'),
      accessory: (
        <Switch
          value={notificationsEnabled}
          onValueChange={onToggleNotifications}
          accessibilityLabel="Notifications"
        />
      ),
    },
    { key: 'privacy', label: 'Privacy', onPress: () => onNavigate('privacy'),
      accessory: <Chevron color={theme.textMuted} /> },
    { key: 'security', label: 'Security', onPress: () => onNavigate('security'),
      accessory: <Chevron color={theme.textMuted} /> },
    { key: 'language', label: 'Language', onPress: () => onNavigate('language'),
      accessory: <Chevron color={theme.textMuted} /> },
    { key: 'help', label: 'Help & Support', onPress: () => onNavigate('help'),
      accessory: <Chevron color={theme.textMuted} /> },
    { key: 'about', label: 'About', onPress: () => onNavigate('about'),
      accessory: <Chevron color={theme.textMuted} /> },
  ];

  return (
    <ScrollView
      style={{ backgroundColor: theme.bgApp }}
      contentContainerStyle={{
        paddingTop: insets.top + 16,
        paddingBottom: insets.bottom + 32,
        paddingHorizontal: 16,
      }}
      contentInsetAdjustmentBehavior="automatic"
    >
      <Pressable
        onPress={onEditProfile}
        accessibilityRole="button"
        accessibilityLabel={`${user.name}, ${user.email}. Edit profile`}
        style={({ pressed }) => [
          styles.profileRow,
          { backgroundColor: pressed ? theme.bgSurfaceRaised : theme.bgSurface, borderColor: theme.borderSubtle },
        ]}
      >
        {user.avatarUrl ? (
          <Image source={{ uri: user.avatarUrl }} style={styles.avatar} accessibilityIgnoresInvertColors />
        ) : (
          <View style={[styles.avatar, styles.avatarFallback, { backgroundColor: theme.accentSolid }]}>
            <Text style={styles.avatarInitial}>{user.name.charAt(0).toUpperCase()}</Text>
          </View>
        )}
        <View style={styles.profileText}>
          <Text style={[styles.profileName, { color: theme.textPrimary }]} numberOfLines={2}>
            {user.name}
          </Text>
          <Text style={[styles.profileEmail, { color: theme.textMuted }]} numberOfLines={2}>
            {user.email}
          </Text>
        </View>
        <Chevron color={theme.textMuted} />
      </Pressable>

      <Text style={[styles.sectionHeading, { color: theme.textMuted }]}>Settings</Text>
      <SectionCard theme={theme}>
        {settingsRows.map((item, i) => (
          <React.Fragment key={item.key}>
            <Row item={item} theme={theme} />
            {i < settingsRows.length - 1 && <Divider theme={theme} />}
          </React.Fragment>
        ))}
      </SectionCard>

      <SectionCard theme={theme}>
        <Row item={{ key: 'logout', label: 'Log Out', onPress: onLogout }} theme={theme} />
      </SectionCard>

      <Text style={[styles.sectionHeading, { color: theme.textMuted }]}>Danger Zone</Text>
      <SectionCard theme={theme}>
        <Row
          item={{
            key: 'delete',
            label: deleting ? 'Deleting\u2026' : 'Delete Account',
            onPress: confirmDelete,
            destructive: true,
            disabled: deleting,
            accessibilityHint: 'Permanently deletes your account. Asks for confirmation first.',
            accessory: deleting ? <ActivityIndicator color={theme.dangerText} /> : undefined,
          }}
          theme={theme}
        />
      </SectionCard>
    </ScrollView>
  );
}

const styles = StyleSheet.create({
  profileRow: {
    flexDirection: 'row',
    alignItems: 'center',
    minHeight: 72,
    borderRadius: 14,
    borderWidth: StyleSheet.hairlineWidth,
    paddingHorizontal: 16,
    paddingVertical: 12,
    gap: 12,
  },
  avatar: { width: 52, height: 52, borderRadius: 26 },
  avatarFallback: { alignItems: 'center', justifyContent: 'center' },
  avatarInitial: { color: '#FFFFFF', fontSize: 20, fontWeight: '600' },
  profileText: { flex: 1, gap: 2 },
  profileName: { fontSize: 17, fontWeight: '600' },
  profileEmail: { fontSize: 14 },
  sectionHeading: {
    fontSize: 13,
    fontWeight: '600',
    textTransform: 'uppercase',
    letterSpacing: 0.4,
    marginTop: 24,
    marginBottom: 8,
    paddingHorizontal: 4,
  },
  card: {
    borderRadius: 14,
    borderWidth: StyleSheet.hairlineWidth,
    overflow: 'hidden',
  },
  row: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    minHeight: 52,
    paddingHorizontal: 16,
    paddingVertical: 14,
    gap: 12,
  },
  rowLabel: { fontSize: 16, flexShrink: 1 },
  divider: { height: StyleSheet.hairlineWidth, marginLeft: 16 },
});
```

Notes:
- Requires `react-native-safe-area-context` (wrap the app in `SafeAreaProvider`); `ActionSheetIOS` and `Alert` are core RN, no extra deps.
- Rows use `minHeight` instead of fixed `height` and don't truncate critical text, so they grow correctly at large Dynamic Type / font-scale sizes.
- Delete confirmation is platform-adaptive by design: an action sheet with a separate Cancel on iOS, a two-button dialog on Android — matching each OS's own destructive-action convention rather than a single cross-platform modal.
- `onDeleteAccount` is caller-supplied and awaited, with a disabled/spinner state on the row to prevent double-taps and a basic failure alert.
